import{_ as u,a0 as p,w as d,s as r,ao as l,I as o,x as n,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"神器：在一个 U 盘上放入多个 Linux 发行版 | LCTT x X-CMD","titleTemplate":false,"description":"神器：在一个 U 盘上放入多个 Linux 发行版 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"神器：在一个 U 盘上放入多个 Linux 发行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"神器：在一个 U 盘上放入多个 Linux 发行版 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210504 Keep multiple Linux distros on a USB with this open source tool","title":"神器：在一个 U 盘上放入多个 Linux 发行版","tag":"202105","desc":""},"relativePath":"202105/20210504 Keep multiple Linux distros on a USB with this open source tool.md","filePath":"[post].md"}'),a={name:"202105/20210504 Keep multiple Linux distros on a USB with this open source tool.md"};function x(m,t,f,y,g,L){const i=p("Link");return d(),r("div",null,[t[39]||(t[39]=l('<h1 id="神器-在一个-u-盘上放入多个-linux-发行版" tabindex="-1">神器：在一个 U 盘上放入多个 Linux 发行版 <a class="header-anchor" href="#神器-在一个-u-盘上放入多个-linux-发行版" aria-label="Permalink to “神器：在一个 U 盘上放入多个 Linux 发行版”">​</a></h1><blockquote><p>用 Ventoy 创建多启动 U 盘，你将永远不会缺少自己喜欢的 Linux 发行版。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/05/131432p5q7hh5cm7a8ffsd.jpg" alt=""></p><p>给朋友和邻居一个可启动 U 盘，里面包含你最喜欢的 Linux 发行版，是向 Linux 新手介绍我们都喜欢的 Linux 体验的好方法。仍然有许多人从未听说过 Linux，把你喜欢的发行版放在一个可启动的 U 盘上是让他们进入 Linux 世界的好办法。</p><p>几年前，我在给一群中学生教授计算机入门课。我们使用旧笔记本电脑，我向学生们介绍了 Fedora、Ubuntu 和 Pop!_OS。下课后，我给每个学生一份他们喜欢的发行版的副本，让他们带回家安装在自己选择的电脑上。他们渴望在家里尝试他们的新技能。</p><h3 id="把多个发行版放在一个驱动器上" tabindex="-1">把多个发行版放在一个驱动器上 <a class="header-anchor" href="#把多个发行版放在一个驱动器上" aria-label="Permalink to “把多个发行版放在一个驱动器上”">​</a></h3>',6)),o("p",null,[t[1]||(t[1]=n("最近，一个朋友向我介绍了 Ventoy，它（根据其 ",-1)),e(i,{href:"https://github.com/ventoy/Ventoy"},{default:s(()=>[...t[0]||(t[0]=[n("GitHub 仓库",-1)])]),_:1}),t[2]||(t[2]=n("）是 “一个开源工具，可以为 ISO/WIM/IMG/VHD(x)/EFI 文件创建可启动的 USB 驱动器”。与其为每个我想分享的 Linux 发行版创建单独的驱动器，我可以在一个 U 盘上放入我喜欢的 ",-1)),t[3]||(t[3]=o("em",null,"所有",-1)),t[4]||(t[4]=n(" Linux 发行版！",-1))]),t[40]||(t[40]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/uploads/ventoy1.png",alt:"USB 空间",title:"USB space"})],-1)),t[41]||(t[41]=o("p",null,"正如你所能想到的那样，U 盘的大小决定了你能在上面容纳多少个发行版。在一个 16GB 的 U 盘上，我放置了 Elementary 5.1、Linux Mint Cinnamon 5.1 和 Linux Mint XFCE 5.1......但仍然有 9.9GB 的空间。",-1)),t[42]||(t[42]=o("h3",{id:"获取-ventoy",tabindex:"-1"},[n("获取 Ventoy "),o("a",{class:"header-anchor",href:"#获取-ventoy","aria-label":"Permalink to “获取 Ventoy”"},"​")],-1)),o("p",null,[t[6]||(t[6]=n("Ventoy 是开源的，采用 ",-1)),e(i,{href:"https://www.ventoy.net/en/doc_license.html"},{default:s(()=>[...t[5]||(t[5]=[n("GPLv3",-1)])]),_:1}),t[7]||(t[7]=n(" 许可证，可用于 Windows 和 Linux。有很好的文档介绍了如何在 Windows 上下载和安装 Ventoy。Linux 的安装是通过命令行进行的，所以如果你不熟悉这个过程，可能会有点混乱。然而，其实很容易。",-1))]),o("p",null,[t[9]||(t[9]=n("首先，",-1)),e(i,{href:"https://github.com/ventoy/Ventoy/releases"},{default:s(()=>[...t[8]||(t[8]=[n("下载 Ventoy",-1)])]),_:1}),t[10]||(t[10]=n("。我把存档文件下载到我的桌面上。",-1))]),t[43]||(t[43]=l('<p>接下来，使用 <code>tar</code> 命令解压 <code>ventoy-x.y.z-linux.tar.gz</code> 档案（但要用你下载的版本号替换 <code>x.y.z</code>）（为了保持简单，我在命令中使用 <code>*</code> 字符作为任意通配符）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvf ventoy*z</span></span></code></pre></div><p>这个命令将所有必要的文件提取到我桌面上一个名为 <code>ventoy-x.y.z</code> 的文件夹中。</p><p>你也可以使用你的 Linux 发行版的存档管理器来完成同样的任务。下载和提取完成后，你就可以把 Ventoy 安装到你的 U 盘上了。</p><h3 id="在-u-盘上安装-ventoy-和-linux" tabindex="-1">在 U 盘上安装 Ventoy 和 Linux <a class="header-anchor" href="#在-u-盘上安装-ventoy-和-linux" aria-label="Permalink to “在 U 盘上安装 Ventoy 和 Linux”">​</a></h3>',5)),o("p",null,[t[12]||(t[12]=n("把你的 U 盘插入你的电脑。改变目录进入 Ventoy 的文件夹，并寻找一个名为 ",-1)),t[13]||(t[13]=o("code",null,"Ventoy2Disk.sh",-1)),t[14]||(t[14]=n(" 的 shell 脚本。你需要确定你的 U 盘的正确挂载点，以便这个脚本能够正常工作。你可以通过在命令行上发出 ",-1)),t[15]||(t[15]=o("code",null,"mount",-1)),t[16]||(t[16]=n(" 命令或者使用 ",-1)),e(i,{href:"https://wiki.gnome.org/Apps/Disks"},{default:s(()=>[...t[11]||(t[11]=[n("GNOME 磁盘",-1)])]),_:1}),t[17]||(t[17]=n(" 来找到它，后者提供了一个图形界面。后者显示我的 U 盘被挂载在 ",-1)),t[18]||(t[18]=o("code",null,"/dev/sda",-1)),t[19]||(t[19]=n("。在你的电脑上，这个位置可能是 ",-1)),t[20]||(t[20]=o("code",null,"/dev/sdb",-1)),t[21]||(t[21]=n(" 或 ",-1)),t[22]||(t[22]=o("code",null,"/dev/sdc",-1)),t[23]||(t[23]=n(" 或类似的位置。",-1))]),t[44]||(t[44]=l('<p><img src="https://opensource.com/sites/default/files/uploads/usb-mountpoint.png" alt="GNOME 磁盘中的 USB 挂载点" title="USB mount point in GNOME Disks"></p><p>下一步是执行 Ventoy shell 脚本。因为它被设计成不加选择地复制数据到一个驱动器上，我使用了一个假的位置（<code>/dev/sdX</code>）来防止你复制/粘贴错误，所以用你想覆盖的实际驱动器的字母替换后面的 <code>X</code>。</p><p><strong>让我重申</strong>：这个 shell 脚本的目的是把数据复制到一个驱动器上， <em>破坏该驱动器上的所有数据。</em> 如果该驱动器上有你关心的数据，在尝试这个方法之前，先把它备份! 如果你不确定你的驱动器的位置，在你继续进行之前，请验证它，直到你完全确定为止。</p><p>一旦你确定了你的驱动器的位置，就运行这个脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sh Ventoy2Disk.sh -i /dev/sdX</span></span></code></pre></div><p>这样就可以格式化它并将 Ventoy 安装到你的 U 盘上。现在你可以复制和粘贴所有适合放在 U 盘上的 Linux 发行版文件。如果你在电脑上用新创建的 U 盘引导，你会看到一个菜单，上面有你复制到 U 盘上的发行版。</p><p><img src="https://opensource.com/sites/default/files/uploads/ventoy_distros.jpg" alt="Ventoy 中的 Linux 发行版" title="Linux distros in Ventoy"></p><h3 id="构建一个便携式的动力源" tabindex="-1">构建一个便携式的动力源 <a class="header-anchor" href="#构建一个便携式的动力源" aria-label="Permalink to “构建一个便携式的动力源”">​</a></h3><p>Ventoy 是你在钥匙串上携带多启动 U 盘的关键（钥匙），这样你就永远不会缺少你所依赖的发行版。你可以拥有一个全功能的桌面、一个轻量级的发行版、一个纯控制台的维护工具，以及其他你想要的东西。</p><p>我从来没有在没有 Linux 发行版的情况下离开家，你也不应该。拿上 Ventoy、一个 U 盘，和一串 ISO。你不会后悔的。</p><hr>',11)),o("p",null,[t[25]||(t[25]=n("via: ",-1)),e(i,{href:"https://opensource.com/article/21/5/linux-ventoy"},{default:s(()=>[...t[24]||(t[24]=[n("https://opensource.com/article/21/5/linux-ventoy",-1)])]),_:1})]),o("p",null,[t[30]||(t[30]=n("作者：",-1)),e(i,{href:"https://opensource.com/users/don-watkins"},{default:s(()=>[...t[26]||(t[26]=[n("Don Watkins",-1)])]),_:1}),t[31]||(t[31]=n(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[27]||(t[27]=[n("lujun9972",-1)])]),_:1}),t[32]||(t[32]=n(" 译者：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[28]||(t[28]=[n("wxy",-1)])]),_:1}),t[33]||(t[33]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[29]||(t[29]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[36]||(t[36]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[34]||(t[34]=[n("LCTT",-1)])]),_:1}),t[37]||(t[37]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:s(()=>[...t[35]||(t[35]=[n("Linux中国",-1)])]),_:1}),t[38]||(t[38]=n(" 荣誉推出",-1))])])}const U=u(a,[["render",x]]);export{T as __pageData,U as default};
